const RM_PSPEC = { fields: ["ช่องที่ต้องมี", "Fields"], docs: ["ชนิดเอกสารที่ต้องมี", "Documents"], doc: ["ชนิดเอกสาร", "Kind of document"], min: ["จำนวนอย่างน้อย", "At least"], above: ["ตั้งแต่วงเงิน (ล้านบาท)", "From (M baht)"], tol: ["คลาดเคลื่อนได้ (%)", "Tolerance (%)"] };
function rmParamsCheck(type, p) {
  rmSyncDocs();
  const T = RM_TYPES[type]; if (!T) return L("เลือกชนิดการตรวจ", "Choose the kind of check");
  for (const [k, kind] of T.spec) { const v = p[k]; if (kind === "fields") { if (!Array.isArray(v) || !v.length || v.some(x => !RM_FLD[x])) return L("เลือกช่องอย่างน้อย 1 ช่อง", "Choose at least one field"); } else if (kind === "docs") { if (!Array.isArray(v) || !v.length || v.some(x => !RM_DOCS.some(d => d[0] === x))) return L("เลือกชนิดเอกสารอย่างน้อย 1 ชนิด", "Choose at least one kind of document"); } else if (kind === "doc") { if (!RM_DOCS.some(d => d[0] === v)) return L("เลือกชนิดเอกสาร", "Choose a kind of document"); } else if (kind === "num") { if (!(Number(v) > 0)) return L(`ค่า "${tx(RM_PSPEC[k])}" ต้องมากกว่า 0`, `"${tx(RM_PSPEC[k])}" must be above 0`); if (k === "tol" && Number(v) > 50) return L("คลาดเคลื่อนต้องไม่เกิน 50%", "Tolerance up to 50%"); } }
  return "";
}
const rmPDesc = c => { const T = RM_TYPES[c.type]; if (!T) return "–"; return T.spec.map(([k, kind]) => { const v = c.params[k]; return `${tx(RM_PSPEC[k])}: ${kind === "fields" ? v.map(x => RM_FLD[x]).join(", ") : kind === "docs" ? v.map(rmDocName).join(", ") : kind === "doc" ? rmDocName(v) : v}`; }).join("; ") || L("ไม่มีค่าให้ตั้ง", "no settings"); };
const rmLaws = () => (S.rmLaw = S.rmLaw || []);
