async function rmFetchSample(i) { const s = RM_SAMPLES[i], out = []; for (const n of s[1]) { const r = await fetch(`ตัวอย่างเอกสารโครงการ/${s[0]}/${n}`); if (!r.ok) throw new Error(`${n}: ${r.status}`); out.push(new File([await r.blob()], n)); } return out; }
