const rmCfgNote = () => eNote(`<b>${L("ยังไม่ได้ยืนยันกับตัวบท:", "Not checked against the text:")}</b> ${L("เครื่องมือค้นหาเว็บใช้ไม่ได้ในรอบที่ทำ จึงไม่มีเลขมาตรา เพดานวงเงิน หรือลิงก์ที่ยืนยันไม่ได้ ทะเบียนเริ่มต้นจากชื่อกฎหมายและเงื่อนไขที่เขียนจากหลักการทั่วไป กองแผนงานเปิดตัวบทจริง กรอกมาตรา/ข้อ ลิงก์ แล้วติ๊ก ตรวจตัวบทแล้ว (ต้องมีทั้งสองอย่าง) ค่าที่เป็นของผู้เขียนเป็นค่าตั้งของเงื่อนไข ไม่ใช่ข้อความของกฎหมาย ทะเบียนนี้เป็นค่ากลางที่เมนู เตรียมคำของบประมาณ ใช้ตรวจเอกสาร", "The web search tools did not work, so no section number, limit or link that could not be verified is given. The register starts from the names of the laws and conditions written from general principles. Planning opens the text, writes the clause and the link and ticks 'checked' (both are needed). The values that are mine are settings of the conditions, not words of the law. This register is the central configuration the menu Make the budget request checks the documents with.")}`);
